SELECT 
FROM sys_process_event_config


        AND process_def_key LIKE CONCAT('%', #{processDefKey}, '%')


        AND process_def_unique_key = #{processDefUniqueKey}


        AND node_def_key LIKE CONCAT('%', #{nodeDefKey}, '%')


        AND submit_action = #{submitAction}


        AND match_business = #{matchBusiness}


        AND change_business_status = #{changeBusinessStatus}


        AND event_type = #{eventType}


        AND event_handler LIKE CONCAT('%', #{eventHandler}, '%')


        AND handler_config LIKE CONCAT('%', #{handlerConfig}, '%')


        AND is_active = #{isActive}


        AND create_user_id = #{createUserId}


        AND update_user_id = #{updateUserId}


        AND create_time >= #{createTime}


        AND update_time >= #{updateTime}


ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

